    // an effective create, and callers that race a prior create get a merge instead.
    const doc = await this.upsert({
        collection: getGlobalSlug(args.slug),
        data: {
            ...args.data,
            id: args.slug
        },
        where: {
            id: {
                equals: args.slug
            }
        }
    });
